insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('saranda', 'Saranda', 'Saranda Forest', 'Jharkhand', 'Sal trees, hills, streams', 'Wild elephant herd', '🐘', 'Haathi the elephant', '🐘', 'Seven hundred hills, one family.', 'Saranda means ''land of seven hundred hills''. It is Asia''s largest sal forest, where wild elephant herds walk old paths between the hills and streams.', '["Togetherness, like a herd","Steady growth, like the sal","Leave every path better than you found it"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#2f6b3f', '#e3a72f', '{"tech":"sal","sports":"sal","culture":"flower"}'::jsonb, 760) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('gir', 'Gir', 'Gir National Park', 'Gujarat', 'Teak and dry scrub, a watering hole', 'Asiatic lion pride', '🦁', 'Sher the lion', '🦁', 'Brave hearts, warm pride.', 'Gir is the only wild home of the Asiatic lion. A few dozen lions once remained; careful protection brought the pride back to hundreds.', '["Courage","Looking after your pride","Comebacks are possible"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#a0662a', '#f2c14e', '{"tech":"teak","sports":"scrub","culture":"flower"}'::jsonb, 440) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('kanha', 'Kanha', 'Kanha National Park', 'Madhya Pradesh', 'Sal and bamboo, open meadows', 'Barasingha (hard-ground swamp deer)', '🦌', 'Bara the swamp deer', '🦌', 'Wide meadows, wider minds.', 'Kanha''s meadows inspired The Jungle Book. It saved the hard-ground barasingha from the brink, one of India''s great conservation stories.', '["Curiosity","Patience","Stories worth telling"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#5b7f2b', '#d9874a', '{"tech":"sal","sports":"bamboo","culture":"flower"}'::jsonb, 345) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('bandipur', 'Bandipur', 'Bandipur National Park', 'Karnataka', 'Teak and rosewood, a river', 'Tiger and elephant', '🐅', 'Bandi the tiger', '🐅', 'Strong alone, stronger together.', 'Bandipur is part of the Nilgiri Biosphere Reserve, where tigers and elephants share teak and rosewood forests along the Moyar river.', '["Strength","Sharing the forest","Calm focus"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#8a3b2a', '#f08a24', '{"tech":"teak","sports":"rosewood","culture":"flower"}'::jsonb, 185) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('corbett', 'Corbett', 'Jim Corbett National Park', 'Uttarakhand', 'Sal forest, the Ramganga river, grasslands', 'Bengal tiger', '🐯', 'Ram the tiger', '🐯', 'First of our kind.', 'Corbett is India''s oldest national park, founded in 1936. The Ramganga river winds through sal forest and grasslands where Bengal tigers roam.', '["Leading the way","Respect for the wild","Discipline"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#c0562b', '#2f6b3f', '{"tech":"sal","sports":"grass","culture":"flower"}'::jsonb, 1525) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('namdapha', 'Namdapha', 'Namdapha National Park', 'Arunachal Pradesh', 'Tall rainforest, misty hills, orchids', 'Red panda', '🦊', 'Nima the red panda', '🦊', 'Rare, wild and curious.', 'Namdapha is a dense rainforest in the eastern Himalaya, rising from steamy valleys to snowy peaks. Red pandas and clouded leopards live in its misty canopy.', '["Curiosity","Celebrating what is rare","Climbing higher"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#b5402e', '#3e7d5a', '{"tech":"rainforest","sports":"rainforest","culture":"orchid"}'::jsonb, 50) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('pichavaram', 'Pichavaram', 'Pichavaram Mangrove Forest', 'Tamil Nadu', 'Mangrove roots, water channels, a boat', 'Flocks of water birds', '🪶', 'Kokku the heron', '🪶', 'Rooted deep, flowing free.', 'Pichavaram is one of the largest mangrove forests in the world. Boats glide through its channels while flocks of water birds gather in the roots.', '["Adaptability","Deep roots","Protecting the shore for others"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#1f6f78', '#7cc3b5', '{"tech":"mangrove","sports":"mangrove","culture":"flower"}'::jsonb, 335) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('wayanad', 'Wayanad', 'Wayanad Wildlife Sanctuary', 'Kerala', 'Evergreen trees, coffee and spice plants, waterfalls', 'Asian elephant', '🐘', 'Kutty the elephant', '🐘', 'Green hills, generous hearts.', 'Wayanad sits in the lush Western Ghats, with evergreen forest, coffee and spice gardens, waterfalls and herds of Asian elephants.', '["Generosity","Growing together","Keeping things green"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#2e7d4f', '#8c5a3c', '{"tech":"evergreen","sports":"coffee","culture":"flower"}'::jsonb, 215) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
insert into public.houses (id, name, place, region, landscape, legendary, legendary_emoji, mascot, mascot_emoji, motto, lore, "values", leaders, color_primary, color_accent, tree_kinds, total_seeds) values ('kaziranga', 'Kaziranga', 'Kaziranga National Park', 'Assam', 'Tall elephant grass, wetlands', 'One-horned rhinoceros', '🦏', 'Gainda the rhino', '🦏', 'Stand firm, stand together.', 'Kaziranga is home to most of the world''s one-horned rhinos, living among tall elephant grass and wetlands on the banks of the Brahmaputra.', '["Resilience","Standing firm","Protecting each other"]'::jsonb, '[{"name":"House Secretary","role":"Secretary"},{"name":"Deputy Secretary","role":"Deputy Secretary"}]'::jsonb, '#4b6b3a', '#9db36b', '{"tech":"grass","sports":"grass","culture":"flower"}'::jsonb, 910) on conflict (id) do update set name = excluded.name, place = excluded.place, region = excluded.region, landscape = excluded.landscape, legendary = excluded.legendary, legendary_emoji = excluded.legendary_emoji, mascot = excluded.mascot, mascot_emoji = excluded.mascot_emoji, motto = excluded.motto, lore = excluded.lore, "values" = excluded."values", leaders = excluded.leaders, color_primary = excluded.color_primary, color_accent = excluded.color_accent, tree_kinds = excluded.tree_kinds, total_seeds = excluded.total_seeds;
