insert into public.quests (id, title, description, track, seeds, starts_at, ends_at, house_id, active, created_at) values ('c67989ac-c779-4b3f-a879-8cd2c9798e65', 'Attend the regional meetup', 'Show up at your region''s meetup and say hello to at least two housemates. Proof: a photo from the meetup.', 'culture', 30, now() - interval '100800 minutes', now() - interval '-10080 minutes', null, true, now() - interval '100800 minutes');
insert into public.quests (id, title, description, track, seeds, starts_at, ends_at, house_id, active, created_at) values ('b317dc10-b417-4da3-a517-df36b617e0c9', 'Solve this week''s tech quiz', 'Take the weekly tech quiz in the house group and score at least 6/10. Proof: a screenshot of your score.', 'tech', 20, now() - interval '100800 minutes', now() - interval '-20160 minutes', null, true, now() - interval '100800 minutes');
insert into public.quests (id, title, description, track, seeds, starts_at, ends_at, house_id, active, created_at) values ('e0834970-e183-4b03-a283-4c96e3834e29', 'Play in the house football match', 'Turn up and play in the inter-house football match. Win or lose, you showed up. Proof: a team photo.', 'sports', 40, now() - interval '100800 minutes', now() - interval '-43200 minutes', null, true, now() - interval '100800 minutes');
insert into public.quests (id, title, description, track, seeds, starts_at, ends_at, house_id, active, created_at) values ('1385ee7b-1285-4ce8-a585-f1a11485f00e', 'Write a poem for the house magazine', 'Write a short poem about your house''s forest and send it to the magazine team. Proof: a link to your poem.', 'culture', 25, now() - interval '100800 minutes', now() - interval '-43200 minutes', null, true, now() - interval '100800 minutes');
insert into public.quests (id, title, description, track, seeds, starts_at, ends_at, house_id, active, created_at) values ('51d490d4-52d4-4267-a3d4-93fa54d4958d', 'Build a tiny web page', 'Make a one-page website about your favourite animal and publish it for free. Proof: the link.', 'tech', 40, now() - interval '100800 minutes', now() - interval '-10080 minutes', null, true, now() - interval '100800 minutes');
