insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('bc815940-bd81-4ad3-ae81-5c66bf815df9', 'saranda', 1, 'Welcome to Saranda', 'Welcome, ranger! Saranda is named after Saranda Forest in Jharkhand. Saranda means ''land of seven hundred hills''. It is Asia''s largest sal forest, where wild elephant herds walk old paths between the hills and streams.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('61a9846b-60a9-42d8-a3a9-879162a985fe', 'saranda', 2, 'Meet Haathi the elephant', 'Haathi the elephant is our mascot. When our forest grows big enough, the wild elephant herd returns to the map. Every quest you finish brings that day closer.', '🐘');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('b2f7dada-b3f7-4c6d-a0f7-d7b4b1f7d947', 'saranda', 3, 'How our forest grows', 'Every quest you complete plants something in the Saranda forest with your name on it: sal trees, hills, streams. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('ee63b04c-ef63-41df-a063-b372f163b505', 'gir', 1, 'Welcome to Gir', 'Welcome, ranger! Gir is named after Gir National Park in Gujarat. Gir is the only wild home of the Asiatic lion. A few dozen lions once remained; careful protection brought the pride back to hundreds.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('938bdb77-928b-49e4-a58b-de9d948bdd0a', 'gir', 2, 'Meet Sher the lion', 'Sher the lion is our mascot. When our forest grows big enough, the asiatic lion pride returns to the map. Every quest you finish brings that day closer.', '🦁');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('443b6546-453b-46d9-a23b-6220433b63b3', 'gir', 3, 'How our forest grows', 'Every quest you complete plants something in the Gir forest with your name on it: teak and dry scrub, a watering hole. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('4f0b422b-4e0b-4098-a10b-4551500b43be', 'kanha', 1, 'Welcome to Kanha', 'Welcome, ranger! Kanha is named after Kanha National Park in Madhya Pradesh. Kanha''s meadows inspired The Jungle Book. It saved the hard-ground barasingha from the brink, one of India''s great conservation stories.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('a9e31700-aae3-4893-abe3-1a26ace31bb9', 'kanha', 2, 'Meet Bara the swamp deer', 'Bara the swamp deer is our mascot. When our forest grows big enough, the barasingha (hard-ground swamp deer) returns to the map. Every quest you finish brings that day closer.', '🦌');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('b56d595d-b46d-47ca-a36d-5637b26d54a4', 'kanha', 3, 'How our forest grows', 'Every quest you complete plants something in the Kanha forest with your name on it: sal and bamboo, open meadows. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('1a4ac18d-194a-4ffa-a84a-be67174abcd4', 'bandipur', 1, 'Welcome to Bandipur', 'Welcome, ranger! Bandipur is named after Bandipur National Park in Karnataka. Bandipur is part of the Nilgiri Biosphere Reserve, where tigers and elephants share teak and rosewood forests along the Moyar river.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('04979d0a-0597-4e9d-a297-99e403979b77', 'bandipur', 2, 'Meet Bandi the tiger', 'Bandi the tiger is our mascot. When our forest grows big enough, the tiger and elephant returns to the map. Every quest you finish brings that day closer.', '🐅');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('b3e8aa5b-b2e8-48c8-a5e8-ad81b4e8abee', 'bandipur', 3, 'How our forest grows', 'Every quest you complete plants something in the Bandipur forest with your name on it: teak and rosewood, a river. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('6e2ea9f7-6d2e-4864-a02e-ad1d6f2eab8a', 'corbett', 1, 'Welcome to Corbett', 'Welcome, ranger! Corbett is named after Jim Corbett National Park in Uttarakhand. Corbett is India''s oldest national park, founded in 1936. The Ramganga river winds through sal forest and grasslands where Bengal tigers roam.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('c9067ecc-ca06-405f-ab06-81f2cc068385', 'corbett', 2, 'Meet Ram the tiger', 'Ram the tiger is our mascot. When our forest grows big enough, the bengal tiger returns to the map. Every quest you finish brings that day closer.', '🐯');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('335423c9-3254-4236-a154-20a330541f10', 'corbett', 3, 'How our forest grows', 'Every quest you complete plants something in the Corbett forest with your name on it: sal forest, the ramganga river, grasslands. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('a5c4db52-a6c4-4ce5-a3c4-d82ca4c4d9bf', 'namdapha', 1, 'Welcome to Namdapha', 'Welcome, ranger! Namdapha is named after Namdapha National Park in Arunachal Pradesh. Namdapha is a dense rainforest in the eastern Himalaya, rising from steamy valleys to snowy peaks. Red pandas and clouded leopards live in its misty canopy.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('bb77ffd5-ba77-4e42-a977-fcafb877fb1c', 'namdapha', 2, 'Meet Nima the red panda', 'Nima the red panda is our mascot. When our forest grows big enough, the red panda returns to the map. Every quest you finish brings that day closer.', '🦊');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('d08bc098-d18b-422b-a28b-c3bed38bc551', 'namdapha', 3, 'How our forest grows', 'Every quest you complete plants something in the Namdapha forest with your name on it: tall rainforest, misty hills, orchids. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('b8d4f296-b9d4-4429-a6d4-ef70b7d4f103', 'pichavaram', 1, 'Welcome to Pichavaram', 'Welcome, ranger! Pichavaram is named after Pichavaram Mangrove Forest in Tamil Nadu. Pichavaram is one of the largest mangrove forests in the world. Boats glide through its channels while flocks of water birds gather in the roots.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('4de97cd9-4ce9-4b46-abe9-79b34ae97820', 'pichavaram', 2, 'Meet Kokku the heron', 'Kokku the heron is our mascot. When our forest grows big enough, the flocks of water birds returns to the map. Every quest you finish brings that day closer.', '🪶');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('639ca15c-649c-42ef-a59c-a482669ca615', 'pichavaram', 3, 'How our forest grows', 'Every quest you complete plants something in the Pichavaram forest with your name on it: mangrove roots, water channels, a boat. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('4571a1a7-4471-4014-a771-a4cd4671a33a', 'wayanad', 1, 'Welcome to Wayanad', 'Welcome, ranger! Wayanad is named after Wayanad Wildlife Sanctuary in Kerala. Wayanad sits in the lush Western Ghats, with evergreen forest, coffee and spice gardens, waterfalls and herds of Asian elephants.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('1faadc3c-20aa-4dcf-a1aa-df6222aae0f5', 'wayanad', 2, 'Meet Kutty the elephant', 'Kutty the elephant is our mascot. When our forest grows big enough, the asian elephant returns to the map. Every quest you finish brings that day closer.', '🐘');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('0b34ec39-0a34-4aa6-a934-e9130834e780', 'wayanad', 3, 'How our forest grows', 'Every quest you complete plants something in the Wayanad forest with your name on it: evergreen trees, coffee and spice plants, waterfalls. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('81b191d0-82b1-4363-a3b1-94f684b19689', 'kaziranga', 1, 'Welcome to Kaziranga', 'Welcome, ranger! Kaziranga is named after Kaziranga National Park in Assam. Kaziranga is home to most of the world''s one-horned rhinos, living among tall elephant grass and wetlands on the banks of the Brahmaputra.', '🌄');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('a778573b-a678-45a8-a978-5a61a87858ce', 'kaziranga', 2, 'Meet Gainda the rhino', 'Gainda the rhino is our mascot. When our forest grows big enough, the one-horned rhinoceros returns to the map. Every quest you finish brings that day closer.', '🦏');
insert into public.lore_cards (id, house_id, position, title, body, emoji) values ('f82749ea-f927-4b7d-a627-46c4f7274857', 'kaziranga', 3, 'How our forest grows', 'Every quest you complete plants something in the Kaziranga forest with your name on it: tall elephant grass, wetlands. If nobody does a quest for a week, the forest starts to wilt. One quest brings the colour back.', '🗺️');
